-- A payment link is a merchant-created, single-use "invoice" a customer
-- pays via the hosted checkout page (apps/web's /pay/:token route). The
-- public identifier is `token`, never the UUID primary key `id` — a
-- sequential/UUID-but-enumerable-by-db-order identifier would let a party
-- with one valid link guess at (or discover, via logs/referrers) another
-- merchant's link by iterating IDs; `token` is generated by
-- lib/crypto.ts's randomToken() (crypto.randomBytes-backed, never
-- Math.random()), giving 128 bits of entropy, and is the ONLY thing a
-- customer's browser ever sees or needs.
--
-- Lifecycle:
--   active -> reserved -> paid            (successful payment)
--   active -> reserved -> active          (declined authorize/capture, or a
--                                          payer abandons mid-flow —
--                                          `reserved` self-expires back to
--                                          `active` after a short timeout;
--                                          derived at read time, no write)
--   active -> canceled                    (merchant DELETE)
-- `expired` is never a stored status — a link stays `active` past its
-- expiry and every reader compares `expires_at` to `now()`. Same for the
-- `reserved` timeout. No sweep job needed for a fact this cheap to compute.
--
-- Links are single-use, so one link produces at most one transaction and a
-- nullable FK is enough (kept in agreement with status by the CHECK below).
-- Multi-pay links would need a join table.

CREATE TABLE payment_links (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    merchant_id      UUID NOT NULL REFERENCES merchants (id),
    token            TEXT NOT NULL UNIQUE,
    amount_fils      BIGINT NOT NULL CHECK (amount_fils > 0),
    currency         CHAR(3) NOT NULL DEFAULT 'BHD' CHECK (currency = 'BHD'),
    reference        TEXT,               -- merchant's own order/invoice id; shown at checkout
    description      TEXT,               -- customer-facing label, e.g. "Invoice #1042"
    status           TEXT NOT NULL DEFAULT 'active'
                         CHECK (status IN ('active', 'reserved', 'paid', 'canceled')),
    expires_at       TIMESTAMPTZ NOT NULL,
    reserved_at      TIMESTAMPTZ,        -- set when a pay attempt claims the link; NULL otherwise
    transaction_id   UUID REFERENCES transactions (id),
    created_by_type  TEXT NOT NULL CHECK (created_by_type IN ('merchant_session', 'merchant_api_key')),
    created_by_id    UUID NOT NULL,      -- sessions.id or api_keys.id, matching request.merchantAuth.actorId
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    paid_at          TIMESTAMPTZ,
    canceled_at      TIMESTAMPTZ,

    -- A link is paid iff it carries a transaction, and vice versa. Encodes
    -- the single-use "one link, at most one transaction" invariant at the
    -- schema level, not just in application code.
    CHECK ((status = 'paid') = (transaction_id IS NOT NULL))
);

-- The only lookup path the public checkout/pay endpoints ever use.
-- (UNIQUE above already creates a supporting btree index; no separate
-- CREATE INDEX needed for token equality lookups.)

-- Backs GET /v1/merchants/:merchantId/payment-links's keyset pagination
-- (apps/api/src/paymentLinks/query.ts), same shape as 0017's
-- idx_transactions_merchant_occurred.
CREATE INDEX idx_payment_links_merchant_created
    ON payment_links (merchant_id, created_at DESC, id DESC);

-- MK (c47c4e0): pay also accepts the terminal's clientNow for the expiry
-- comparison, for offline terminals. the "every reader compares expires_at
-- to now()" line above predates that.
